''');
  });

  tearDownAll(() {
    server?.stop();
    final dirs = [faShots, cwdSandbox, tempHome].whereType<Directory>();
    for (final dir in dirs) {
      if (dir.existsSync()) dir.deleteSync(recursive: true);
    }
